import { useEffect, type RefObject } from "react"

/** Navigate after Radix's portal is connected; moving a navigated frame cancels its context. */
export function UpgradeCheckoutFrame({
  checkoutUrl,
  frame,
  onNavigationStart,
}: {
  checkoutUrl: string
  frame: RefObject<HTMLIFrameElement | null>
  onNavigationStart: () => void
}) {
  useEffect(() => {
    const element = frame.current
    if (!element) return
    let canceled = false
    let pending = 0
    const deadline = Date.now() + 10_000
    const navigate = () => {
      if (canceled || frame.current !== element) return
      if (!element.isConnected) {
        if (Date.now() < deadline) pending = window.requestAnimationFrame(navigate)
        return
      }
      onNavigationStart()
      element.src = checkoutUrl
    }
    pending = window.requestAnimationFrame(navigate)
    return () => {
      canceled = true
      window.cancelAnimationFrame(pending)
    }
  }, [checkoutUrl, frame, onNavigationStart])

  return (
    <iframe
      ref={frame}
      title="MapSVG upgrade secure checkout"
      allow="payment"
      loading="eager"
      referrerPolicy="no-referrer"
      className="h-full w-full border-0"
      onLoad={onNavigationStart}
    />
  )
}
