import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"
import { MapSVGApiError } from "@/lib/global-settings-api"

export type UpgradePlan = {
  priceId: string
  slug: string
  title: string
  amountMinor: number
  currency: string
  billingCycle?: { interval: "day" | "week" | "month" | "year"; frequency: number } | null
  numDomainsMax: number
  version?: string
  requiresLiteVersion?: string
  requiresAddonApi?: number
  updateRequired?: boolean
  aiCredits?: { qty: number; period: "day" | "week" | "month" | "year" }
}
export type UpgradePurchase = { purchaseId: string; checkoutUrl: string }
export type UpgradeInstallation = {
  purchaseId: string
  slug: string
  status: "fulfilled"
  manualDownloadUrl?: string
}
export type UpgradeCatalogue = {
  accountEmail?: string
  uploadMaxBytes?: number
  plans: UpgradePlan[]
  license: { id: string; [key: string]: unknown }
  installation?: UpgradeInstallation | null
}
export type UpgradeStatus = {
  accountEmail?: string
  purchaseId: string
  status: string
  licenseId: string
  slug?: string
  manualDownloadUrl?: string
}
async function request<T>(path: string, body?: unknown, timeoutMs = 20_000): Promise<T> {
  const params = getAdminParams()
  const controller = new AbortController()
  const timer = window.setTimeout(() => controller.abort(), timeoutMs)
  try {
    const response = await adminRestFetch(
      `${params.apiUrl.replace(/\/?$/, "")}/license-upgrades${path}`,
      {
        method: body === undefined ? "GET" : "POST",
        credentials: "same-origin",
        cache: "no-store",
        signal: controller.signal,
        headers: {
          Accept: "application/json",
          "X-WP-Nonce": params.nonce,
          ...(body === undefined ? {} : { "Content-Type": "application/json" }),
        },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      },
    )
    const data = await response.json().catch(() => null)
    if (!response.ok)
      throw new MapSVGApiError(
        data?.error || data?.message || "Could not complete the upgrade. Please try again.",
        response.status,
        data,
      )
    if (!data || typeof data !== "object")
      throw new Error("MapSVG returned an invalid upgrade response.")
    return data as T
  } finally {
    window.clearTimeout(timer)
  }
}

export const getUpgradePlans = () => request<UpgradeCatalogue>("/plans")
export const createUpgradePurchase = (priceId: string, requestId: string) =>
  request<UpgradePurchase>("/purchases", { priceId, requestId })
export const getUpgradePurchase = (purchaseId: string) =>
  request<UpgradeStatus>(`/purchases/${encodeURIComponent(purchaseId)}`)

export type UploadedUpgradeResult = {
  installed: true
  reloadRequired: true
  slug: string
  version: string
}

/** A file chosen by the administrator is the only package source. Never accept a URL. */
export async function installUploadedUpgrade(
  purchaseId: string,
  pluginZip: File,
): Promise<UploadedUpgradeResult> {
  const params = getAdminParams()
  const body = new FormData()
  body.append("purchaseId", purchaseId)
  body.append("pluginZip", pluginZip, pluginZip.name)
  const controller = new AbortController()
  const timer = window.setTimeout(() => controller.abort(), 180_000)
  try {
    const response = await adminRestFetch(
      `${params.apiUrl.replace(/\/?$/, "")}/license-upgrades/install-upload`,
      {
        method: "POST",
        credentials: "same-origin",
        cache: "no-store",
        body,
        signal: controller.signal,
        // The browser supplies the multipart boundary. JSON headers would corrupt the upload.
        headers: { Accept: "application/json", "X-WP-Nonce": params.nonce },
      },
    )
    const data = await response.json().catch(() => null)
    if (!response.ok)
      throw new MapSVGApiError(
        data?.error ||
          data?.message ||
          "Could not install your uploaded ZIP. Try again or upload it from WordPress Plugins.",
        response.status,
        data,
      )
    if (!data || typeof data !== "object")
      throw new Error("WordPress returned an invalid installation response.")
    return data as UploadedUpgradeResult
  } finally {
    window.clearTimeout(timer)
  }
}
