import { useEffect, useRef, useState } from "react"
import { createPortal } from "react-dom"
import { usePortalContainer } from "@/lib/shadow-root"

const COLORS = ["#f59e0b", "#ec4899", "#8b5cf6", "#3b82f6", "#22c55e", "#ef4444"]

/** One decorative burst per ready-screen entry, outside the modal's clipping box. */
export function UpgradeCelebration() {
  const origin = useRef<HTMLSpanElement>(null)
  const overlay = useRef<HTMLDivElement>(null)
  const portal = usePortalContainer()
  const [replay, setReplay] = useState(0)

  useEffect(() => {
    const preview = (event: KeyboardEvent) => {
      if (
        event.code !== "KeyC" ||
        !event.altKey ||
        !event.shiftKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.repeat
      )
        return
      event.preventDefault()
      event.stopPropagation()
      setReplay((value) => value + 1)
    }
    window.addEventListener("keydown", preview, true)
    return () => window.removeEventListener("keydown", preview, true)
  }, [])

  useEffect(() => {
    const layer = overlay.current
    const anchor = origin.current
    if (!layer || !anchor || !Element.prototype.animate) return
    const motion = window.matchMedia?.("(prefers-reduced-motion: reduce)")
    if (motion?.matches) return
    const animations: Animation[] = []
    const stop = () => {
      animations.forEach((animation) => animation.cancel())
      layer.replaceChildren()
    }
    const onMotionChange = () => {
      if (motion?.matches) stop()
    }
    motion?.addEventListener("change", onMotionChange)
    // Let the dialog's entrance transform settle before measuring the popper.
    const timer = window.setTimeout(() => {
      const point = anchor.getBoundingClientRect()
      const bounds = layer.getBoundingClientRect()
      const x = point.left + point.width / 2 - bounds.left
      const y = point.top + point.height / 2 - bounds.top
      if (motion?.matches) return
      for (let index = 0; index < 64; index++) {
        const piece = document.createElement("span")
        const duration = 2800 + Math.random() * 1200
        const velocityX = (Math.random() - 0.5) * bounds.width * 1.25
        const velocityY = -bounds.height * (0.4 + Math.random() * 0.35)
        const rotation = Math.random() * 360
        const spin = (Math.random() - 0.5) * 1440
        Object.assign(piece.style, {
          position: "absolute",
          left: "0",
          top: "0",
          width: "6px",
          height: "10px",
          borderRadius: index % 3 === 0 ? "50%" : "1px",
          backgroundColor: COLORS[index % COLORS.length],
        })
        layer.appendChild(piece)
        const frames = Array.from({ length: 25 }, (_, step) => {
          const progress = step / 24
          const seconds = (progress * duration) / 1000
          const dx = x + velocityX * seconds * 0.55
          const dy = y + velocityY * seconds + 0.5 * bounds.height * 0.85 * seconds ** 2
          return {
            offset: progress,
            transform: `translate3d(${dx}px, ${dy}px, 0) rotate(${rotation + spin * progress}deg) rotateY(${progress * 720}deg)`,
            opacity: progress > 0.8 ? (1 - progress) / 0.2 : 1,
          }
        })
        const animation = piece.animate(frames, { duration, easing: "linear", fill: "both" })
        animations.push(animation)
        void animation.finished.then(
          () => piece.remove(),
          () => {},
        )
      }
    }, 220)
    return () => {
      window.clearTimeout(timer)
      motion?.removeEventListener("change", onMotionChange)
      stop()
    }
  }, [portal, replay])

  return (
    <>
      <span ref={origin} aria-hidden="true" className="block text-[32px] leading-8">
        🎉
      </span>
      {createPortal(
        <div
          ref={overlay}
          aria-hidden="true"
          data-slot="upgrade-confetti"
          className="pointer-events-none fixed inset-0 z-[60] overflow-hidden"
        />,
        portal ?? document.body,
      )}
    </>
  )
}
