import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react"
import {
  ArrowLeft,
  Check,
  ChevronRight,
  ExternalLink,
  Globe,
  Sparkles,
  Download,
  Upload,
  X,
} from "lucide-react"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Spinner } from "@/components/ui/spinner"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { LicenseSettingsPage } from "./LicenseSettingsPage"
import { LiteEnrollmentForm } from "./UsageDialog"
import { UpgradeCheckoutFrame } from "./UpgradeCheckoutFrame"
import { UpgradeCelebration } from "./UpgradeCelebration"
import { getAdminParams, isLitePlan } from "@/lib/admin-params"
import { getAiUsage, MapSVGApiError } from "@/lib/global-settings-api"
import { useLicenseSummary } from "@/lib/use-license-summary"
import {
  createUpgradePurchase,
  getUpgradePlans,
  getUpgradePurchase,
  installUploadedUpgrade,
  type UpgradeCatalogue,
  type UpgradePlan,
  type UpgradePurchase,
  type UpgradeStatus,
} from "@/lib/license-upgrade-api"
import { cn } from "@/lib/utils"

const INITIAL_HEIGHT = 1000
const CONFIRMATION_TIMEOUT_MS = 120_000
const PLAN_NAMES: Record<string, string | undefined> = {
  "mapsvg-personal": "MapSVG Personal",
  "mapsvg-professional": "MapSVG Professional",
  "mapsvg-business": "MapSVG Business",
}
const PLAN_AI_USAGE_LABELS: Record<string, string | undefined> = {
  "mapsvg-personal": "Standard AI usage",
  "mapsvg-professional": "x3 AI usage",
  "mapsvg-business": "x5 AI usage",
}
const unavailableCheckoutCodes = new Set([
  "upgrade_purchase_superseded",
  "upgrade_purchase_canceled",
])
class UpgradeVerificationError extends Error {}

function upgradeErrorCode(failure: unknown): string | undefined {
  if (!(failure instanceof MapSVGApiError)) return undefined
  const code =
    failure.payload?.code ?? (failure.payload?.data as Record<string, unknown> | undefined)?.code
  return typeof code === "string" ? code : undefined
}
type Phase = "checkout" | "confirming" | "verification-error" | "complete"

function planPrice(plan: UpgradePlan) {
  const amount = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: plan.currency,
  }).format(plan.amountMinor / 100)
  const cycle = plan.billingCycle
  return `${amount}${cycle ? ` / ${cycle.frequency > 1 ? `${cycle.frequency} ${cycle.interval}s` : cycle.interval}` : " one-time"}`
}

function safeDownloadUrl(value: unknown): string | null {
  if (typeof value !== "string" || !value) return null
  try {
    const url = new URL(value, window.location.href)
    return url.origin === window.location.origin && ["http:", "https:"].includes(url.protocol)
      ? url.href
      : null
  } catch {
    return null
  }
}

/** Server verification grants the upgrade; installation is an explicit manual WordPress action. */
export function UpgradeDialog({
  open,
  onOpenChange,
  onReloadEditor,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  onReloadEditor?: () => Promise<void>
}) {
  const params = getAdminParams()
  const summary = useLicenseSummary()
  const bootActivated = Boolean(summary?.hasCode && summary.ok)
  const [activationRequired, setActivationRequired] = useState(false)
  const activated = bootActivated && !activationRequired
  const [catalogue, setCatalogue] = useState<UpgradeCatalogue | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [purchase, setPurchase] = useState<UpgradePurchase | null>(null)
  const [verificationPurchaseId, setVerificationPurchaseId] = useState<string | null>(null)
  const [selectedPriceId, setSelectedPriceId] = useState("")
  const [checkoutLoading, setCheckoutLoading] = useState(false)
  const [processing, setProcessing] = useState(false)
  const [frameHeight, setFrameHeight] = useState(INITIAL_HEIGHT)
  const [phase, setPhase] = useState<Phase>("checkout")
  const [verificationError, setVerificationError] = useState("")
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null)
  const [purchasedPlanSlug, setPurchasedPlanSlug] = useState("")
  const [accountEmail, setAccountEmail] = useState("")
  const [pluginZip, setPluginZip] = useState<File | null>(null)
  const [uploadError, setUploadError] = useState("")
  const [uploadState, setUploadState] = useState<"idle" | "installing" | "installed" | "reloading">(
    "idle",
  )
  const [dragging, setDragging] = useState(false)
  const fileInput = useRef<HTMLInputElement>(null)
  const installPending = useRef(false)
  const reloadPending = useRef(false)
  const installedPurchase = useRef<{ purchaseId: string; slug: string } | null>(null)
  const reloadEditorRef = useRef(onReloadEditor)
  reloadEditorRef.current = onReloadEditor
  const choiceId = useId()
  const downloadTarget = `mapsvg-upgrade-download-${choiceId.replace(/[^a-zA-Z0-9_-]/g, "")}`
  const content = useRef<HTMLDivElement>(null)
  const frame = useRef<HTMLIFrameElement>(null)
  const body = useRef<HTMLDivElement>(null)
  const choices = useRef<HTMLDivElement>(null)
  const epoch = useRef(0)
  const selection = useRef(0)
  const mountedOpen = useRef(open)
  mountedOpen.current = open
  const completed = useRef(false)
  const refreshedPurchases = useRef(new Set<string>())
  // An order belongs only to the current selection. A different plan supersedes its checkout.
  const order = useRef<{ priceId: string; requestId: string; purchase?: UpgradePurchase } | null>(
    null,
  )
  const loadRef = useRef<() => Promise<void>>(async () => {})
  const resetCheckoutScroll = useCallback(() => {
    if (body.current) body.current.scrollTop = 0
  }, [])

  useEffect(() => {
    if (!open || (!loading && !checkoutLoading)) return
    resetCheckoutScroll()
    const pending = window.requestAnimationFrame(resetCheckoutScroll)
    return () => window.cancelAnimationFrame(pending)
  }, [open, loading, checkoutLoading, selectedPriceId, purchase?.purchaseId, resetCheckoutScroll])

  const checkoutUnavailable = useCallback((message: string) => {
    order.current = null
    setPurchase(null)
    setVerificationPurchaseId(null)
    setProcessing(false)
    setCheckoutLoading(false)
    setPhase("checkout")
    setError(message)
  }, [])

  const showUpgradeReady = useCallback((result: UpgradeStatus) => {
    completed.current = true
    setPurchasedPlanSlug(result.slug || "")
    setDownloadUrl(safeDownloadUrl(result.manualDownloadUrl))
    if (result.accountEmail) setAccountEmail(result.accountEmail)
    setProcessing(false)
    setCheckoutLoading(false)
    setVerificationError("")
    setPhase("complete")
    if (
      installedPurchase.current?.purchaseId === result.purchaseId &&
      installedPurchase.current.slug === result.slug
    )
      setUploadState("installed")
    if (body.current) body.current.scrollTop = 0
    if (!refreshedPurchases.current.has(result.purchaseId)) {
      refreshedPurchases.current.add(result.purchaseId)
      // Refresh authoritative quota independently; download instructions stay usable
      // even when the optional usage request fails or the modal is closed.
      void getAiUsage()
        .then((data) => {
          window.dispatchEvent(
            new CustomEvent("mapsvg:ai-usage-updated", {
              detail: { licenses: data.licenses, purchaseCompleted: true },
            }),
          )
        })
        .catch(() => {})
    }
  }, [])

  const selectPlan = useCallback(async (plan: UpgradePlan) => {
    if (completed.current) return
    const current = epoch.current
    const selected = ++selection.current
    const previousOrder = order.current
    setSelectedPriceId(plan.priceId)
    setPurchase(null)
    setVerificationPurchaseId(null)
    setError("")
    if (plan.updateRequired) {
      setCheckoutLoading(false)
      return
    }
    setCheckoutLoading(true)
    setFrameHeight(INITIAL_HEIGHT)
    setError("")
    if (order.current?.priceId !== plan.priceId)
      order.current = { priceId: plan.priceId, requestId: crypto.randomUUID() }
    const requestId = order.current.requestId
    try {
      const result = await createUpgradePurchase(plan.priceId, requestId)
      if (mountedOpen.current && current === epoch.current && selected === selection.current) {
        if (order.current?.requestId === requestId) order.current.purchase = result
        setPurchase(result)
      }
    } catch (failure) {
      if (mountedOpen.current && current === epoch.current && selected === selection.current) {
        const code = upgradeErrorCode(failure)
        if (code && unavailableCheckoutCodes.has(code)) order.current = null
        if (code === "upgrade_license_changed" || code === "upgrade_lite_update_required") {
          order.current = null
          void loadRef.current()
          return
        }
        if (code === "upgrade_payment_processing") {
          setProcessing(true)
          const existingId = failure instanceof MapSVGApiError ? failure.payload?.purchaseId : null
          const verifyingId =
            typeof existingId === "string" ? existingId : previousOrder?.purchase?.purchaseId
          if (verifyingId) {
            order.current = previousOrder
            setVerificationPurchaseId(verifyingId)
            setPhase("confirming")
            setCheckoutLoading(false)
            return
          }
        }
        setCheckoutLoading(false)
        setError(failure instanceof Error ? failure.message : "Could not prepare checkout.")
      }
    }
  }, [])

  const load = useCallback(async () => {
    const current = ++epoch.current
    selection.current++
    setLoading(true)
    setError("")
    try {
      const data = await getUpgradePlans()
      if (!mountedOpen.current || current !== epoch.current) return
      setCatalogue(data)
      setAccountEmail(data.accountEmail || "")
      setActivationRequired(false)
      if (data.installation) setPhase("confirming")
      else if (data.plans[0]) void selectPlan(data.plans[0])
    } catch (failure) {
      if (mountedOpen.current && current === epoch.current) {
        if (failure instanceof MapSVGApiError && failure.payload?.code === "activation_required")
          setActivationRequired(true)
        setError(failure instanceof Error ? failure.message : "Could not load upgrade plans.")
      }
    } finally {
      if (mountedOpen.current && current === epoch.current) setLoading(false)
    }
  }, [selectPlan])
  loadRef.current = load

  useEffect(() => {
    setCatalogue(null)
    setActivationRequired(false)
    setPurchase(null)
    setVerificationPurchaseId(null)
    setSelectedPriceId("")
    setCheckoutLoading(false)
    setProcessing(false)
    setFrameHeight(INITIAL_HEIGHT)
    setPhase("checkout")
    setError("")
    setVerificationError("")
    setDownloadUrl(null)
    setPurchasedPlanSlug("")
    setPluginZip(null)
    setUploadError("")
    setUploadState("idle")
    setDragging(false)
    installPending.current = false
    reloadPending.current = false
    completed.current = false
    setAccountEmail("")
    order.current = null
    if (open && bootActivated) void load()
    else setLoading(false)
    return () => {
      epoch.current++
      selection.current++
    }
  }, [open, bootActivated, summary, load])

  const purchaseId =
    verificationPurchaseId ?? purchase?.purchaseId ?? catalogue?.installation?.purchaseId
  useEffect(() => {
    if (
      !open ||
      !activated ||
      !purchaseId ||
      phase === "verification-error" ||
      phase === "complete"
    )
      return
    const current = epoch.current
    const selected = selection.current
    let disposed = false,
      pending = false,
      failures = 0
    const verify = async () => {
      if (disposed || pending) return
      pending = true
      try {
        const result = await getUpgradePurchase(purchaseId)
        if (disposed || current !== epoch.current || selected !== selection.current) return
        if (result.purchaseId !== purchaseId || result.licenseId !== catalogue?.license.id)
          throw new UpgradeVerificationError("This purchase does not match the activated license.")
        failures = 0
        if (result.status === "fulfilled") showUpgradeReady(result)
        else if (["superseded", "canceled"].includes(result.status)) {
          disposed = true
          checkoutUnavailable(
            "This checkout is no longer available. Choose your plan or try again to open a new checkout.",
          )
        } else if (result.status === "processing") setProcessing(true)
        else if (!["ready", "creating"].includes(result.status))
          throw new UpgradeVerificationError(
            "This checkout is no longer available. Your paid license, if completed, remains in Dashboard.",
          )
      } catch (failure) {
        if (disposed || current !== epoch.current || selected !== selection.current) return
        const code = upgradeErrorCode(failure)
        if (code && unavailableCheckoutCodes.has(code)) {
          disposed = true
          checkoutUnavailable(
            failure instanceof Error ? failure.message : "This checkout is no longer available.",
          )
          return
        }
        failures++
        if (
          failures >= 6 ||
          failure instanceof UpgradeVerificationError ||
          (failure instanceof MapSVGApiError && [400, 401, 403, 404, 410].includes(failure.status))
        ) {
          disposed = true
          setPhase("verification-error")
          setCheckoutLoading(false)
          setVerificationError(
            failure instanceof Error
              ? failure.message
              : "Could not check your payment. Retry without starting another purchase.",
          )
        }
      } finally {
        pending = false
      }
    }
    void verify()
    const timer = window.setInterval(() => void verify(), 2500)
    return () => {
      disposed = true
      window.clearInterval(timer)
    }
  }, [
    open,
    activated,
    purchaseId,
    phase,
    catalogue?.license.id,
    showUpgradeReady,
    checkoutUnavailable,
  ])

  useEffect(() => {
    if (!open || !purchase) return
    const message = (event: MessageEvent) => {
      if (
        event.origin !== new URL(purchase.checkoutUrl).origin ||
        event.source !== frame.current?.contentWindow ||
        event.data?.purchaseId !== purchase.purchaseId
      )
        return
      if (
        event.data.type === "mapsvg:license-upgrade-checkout-height" &&
        Number.isFinite(event.data.height)
      )
        setFrameHeight(Math.max(300, Math.min(1600, event.data.height)))
      if (event.data.type !== "mapsvg:license-upgrade-purchase") return
      // A delayed frame event must not return a paid order to an editable checkout.
      if (phase !== "checkout") return
      if (event.data.status === "loaded") {
        setCheckoutLoading(false)
        choices.current
          ?.querySelector<HTMLButtonElement>('[aria-checked="true"]')
          ?.focus({ preventScroll: true })
        if (body.current) body.current.scrollTop = 0
      } else if (["processing", "paid", "fulfilled"].includes(event.data.status)) {
        setProcessing(true)
        if (event.data.status === "paid" || event.data.status === "fulfilled")
          setPhase("confirming")
      } else if (event.data.status === "ready" || event.data.status === "error") {
        setProcessing(false)
        setCheckoutLoading(false)
      } else if (["superseded", "canceled"].includes(event.data.status)) {
        checkoutUnavailable(
          "This checkout is no longer available. Choose your plan or try again to open a new checkout.",
        )
      }
    }
    window.addEventListener("message", message)
    return () => window.removeEventListener("message", message)
  }, [open, purchase, phase, checkoutUnavailable])

  useEffect(() => {
    if (!open || phase !== "confirming") return
    const timeout = window.setTimeout(() => {
      setPhase("verification-error")
      setCheckoutLoading(false)
      setVerificationError(
        "Payment confirmation is taking longer than expected. Check its status without starting another purchase.",
      )
    }, CONFIRMATION_TIMEOUT_MS)
    return () => window.clearTimeout(timeout)
  }, [open, phase, purchaseId])

  const uploadMaxBytes =
    catalogue?.uploadMaxBytes && catalogue.uploadMaxBytes > 0
      ? catalogue.uploadMaxBytes
      : 50 * 1024 * 1024
  const selectPluginZip = (files: File[]) => {
    if (installPending.current || uploadState === "installed" || uploadState === "reloading") return
    setPluginZip(null)
    setUploadError("")
    if (files.length !== 1) {
      setUploadError("Choose one plugin ZIP file.")
      return
    }
    const file = files[0]
    if (!/\.zip$/i.test(file.name)) {
      setUploadError("Choose a plugin file in .zip format.")
      return
    }
    if (!file.size) {
      setUploadError("This ZIP file is empty. Choose the downloaded plugin ZIP.")
      return
    }
    if (file.size > uploadMaxBytes) {
      setUploadError(
        `This ZIP is too large. The upload limit is ${Math.round((uploadMaxBytes / 1024 / 1024) * 10) / 10} MB.`,
      )
      return
    }
    setPluginZip(file)
  }
  const installSelectedZip = async () => {
    if (!pluginZip || !purchaseId || !completed.current || installPending.current) return
    const current = epoch.current
    installPending.current = true
    setUploadError("")
    setUploadState("installing")
    try {
      const result = await installUploadedUpgrade(purchaseId, pluginZip)
      if (!mountedOpen.current || current !== epoch.current) return
      if (
        result.installed !== true ||
        result.reloadRequired !== true ||
        result.slug !== purchasedPlanSlug
      )
        throw new Error(
          "WordPress did not confirm installation of your purchased plan. Retry or upload the ZIP from WordPress Plugins.",
        )
      installedPurchase.current = { purchaseId, slug: result.slug }
      setUploadState("installed")
    } catch (failure) {
      if (mountedOpen.current && current === epoch.current) {
        setUploadState("idle")
        setUploadError(
          failure instanceof Error
            ? failure.message
            : "Could not install the uploaded ZIP. Try again or use WordPress Plugins → Add New Plugin → Upload Plugin.",
        )
      }
    } finally {
      installPending.current = false
    }
  }
  const reloadEditor = async () => {
    if (!reloadEditorRef.current || uploadState !== "installed" || reloadPending.current) return
    reloadPending.current = true
    const current = epoch.current
    setUploadError("")
    setUploadState("reloading")
    try {
      await reloadEditorRef.current()
      if (mountedOpen.current && current === epoch.current) setUploadState("installed")
    } catch (failure) {
      if (mountedOpen.current && current === epoch.current) {
        setUploadState("installed")
        setUploadError(
          failure instanceof Error
            ? failure.message
            : "Could not save your workspace before reloading. Save your changes and try again.",
        )
      }
    } finally {
      reloadPending.current = false
    }
  }
  const packageInstalled = uploadState === "installed" || uploadState === "reloading"
  const uploadBusy = uploadState === "installing" || uploadState === "reloading"
  // A file dropped outside the target must never navigate away from the retained editor.
  useEffect(() => {
    if (!open || phase !== "complete") return
    const preventFileNavigation = (event: DragEvent) => {
      if (Array.from(event.dataTransfer?.types || []).includes("Files")) event.preventDefault()
    }
    window.addEventListener("dragover", preventFileNavigation)
    window.addEventListener("drop", preventFileNavigation)
    return () => {
      window.removeEventListener("dragover", preventFileNavigation)
      window.removeEventListener("drop", preventFileNavigation)
    }
  }, [open, phase])
  const locked = open && (phase === "confirming" || uploadBusy)
  useLayoutEffect(() => {
    if (!locked) return
    // Radix keeps the modal focused; inert also covers the surrounding WordPress
    // controls across the admin ShadowRoot. Capture prevents background shortcuts
    // and activation handlers from running before the modal's dismissal handlers.
    const restore: Array<() => void> = []
    let branch: Element | null = content.current
    while (branch && branch !== document.body) {
      const parent = branch.parentNode
      if (!(parent instanceof Element || parent instanceof ShadowRoot)) break
      for (const sibling of parent.children) {
        if (sibling === branch || sibling.hasAttribute("inert")) continue
        sibling.setAttribute("inert", "")
        restore.push(() => sibling.removeAttribute("inert"))
      }
      branch = parent instanceof ShadowRoot ? parent.host : parent
    }
    const block = (event: Event) => {
      event.preventDefault()
      event.stopImmediatePropagation()
    }
    const blockedEvents = ["click", "auxclick", "dblclick", "pointerdown", "keydown", "submit"]
    for (const type of blockedEvents) window.addEventListener(type, block, true)
    content.current?.focus({ preventScroll: true })
    return () => {
      for (const type of blockedEvents) window.removeEventListener(type, block, true)
      for (const undo of restore.reverse()) undo()
    }
  }, [locked])
  const confirmationView = phase !== "checkout" || Boolean(catalogue?.installation)
  const purchasedPlanName = PLAN_NAMES[purchasedPlanSlug] || "MapSVG"
  const dashboardUrl = params.dashboardUrl || "https://mapsvg.com/dashboard"
  const selectedPlan = catalogue?.plans.find((plan) => plan.priceId === selectedPriceId)
  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!locked) onOpenChange(next)
      }}
    >
      <DialogContent
        ref={content}
        aria-describedby={undefined}
        aria-busy={locked}
        showCloseButton={!locked}
        onEscapeKeyDown={(event) => {
          if (locked) event.preventDefault()
        }}
        // ShadowRoot/iframe focus can be retargeted as an outside interaction.
        // Checkout uses explicit Close/Go back (and Escape before payment).
        onInteractOutside={(event) => event.preventDefault()}
        className={cn(
          "flex max-h-[85vh] flex-col gap-0 overflow-hidden p-0 sm:max-w-3xl",
          activated && "h-[85vh]",
        )}
      >
        <DialogHeader className="shrink-0 border-b border-border px-6 py-5">
          <DialogTitle>
            {phase === "complete"
              ? packageInstalled
                ? "Installed"
                : "Payment confirmed"
              : activated
                ? "Checkout"
                : "Upgrade MapSVG"}
          </DialogTitle>
        </DialogHeader>
        <div
          ref={body}
          className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-6"
          data-slot="upgrade-body"
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
          onFocusCapture={() => {
            if (loading || checkoutLoading) resetCheckoutScroll()
          }}
        >
          {!activated ? (
            <div className="space-y-6">
              <SettingsSection
                title="Activate your Lite license"
                help="Activate your existing key, or verify your email to get a free Lite key before upgrading. Your license ID and key stay the same when you upgrade."
                hideDivider
              >
                <LicenseSettingsPage activationOnly />
              </SettingsSection>
              {isLitePlan(params.licenseProductSlug || params.plan) ? <LiteEnrollmentForm /> : null}
            </div>
          ) : confirmationView ? (
            phase === "complete" ? (
              <div className="flex min-h-full flex-col justify-center gap-6">
                <div className="space-y-3 text-center">
                  {packageInstalled ? (
                    <Check aria-hidden="true" className="mx-auto size-8" />
                  ) : (
                    <UpgradeCelebration />
                  )}
                  <h2 className="text-lg font-semibold">
                    {packageInstalled
                      ? `${purchasedPlanName} is installed and active`
                      : `Your ${purchasedPlanName} upgrade is ready`}
                  </h2>
                  {packageInstalled ? (
                    <p className="text-sm text-muted-foreground">
                      Reload the editor when you are ready to use your new features.
                    </p>
                  ) : null}
                </div>
                <div
                  className="my-6 grid grid-cols-1 gap-4 sm:grid-cols-2 sm:grid-rows-[auto_auto_auto]"
                  data-slot="upgrade-package-actions"
                >
                  <div className="grid min-w-0 items-center justify-items-center gap-3 rounded-lg border p-4 text-center sm:row-span-3 sm:grid-rows-subgrid">
                    <Download aria-hidden="true" className="size-6 text-muted-foreground" />
                    <p className="flex self-stretch items-center justify-center text-sm font-medium">
                      Download your plugin
                    </p>
                    {uploadBusy ? (
                      <Button disabled>Download {purchasedPlanName}</Button>
                    ) : (
                      <Button asChild>
                        <a
                          href={downloadUrl || dashboardUrl}
                          target={downloadUrl ? downloadTarget : "_blank"}
                          rel={downloadUrl ? undefined : "noreferrer"}
                          referrerPolicy="no-referrer"
                        >
                          <Download aria-hidden="true" className="size-4" />
                          {downloadUrl
                            ? `Download ${purchasedPlanName}`
                            : "Download from Dashboard"}
                        </a>
                      </Button>
                    )}
                    {downloadUrl ? (
                      <iframe
                        name={downloadTarget}
                        title="Plugin download"
                        hidden
                        aria-hidden="true"
                        referrerPolicy="no-referrer"
                      />
                    ) : null}
                  </div>
                  <div
                    className={cn(
                      "grid min-w-0 items-center justify-items-center gap-3 rounded-lg border border-dashed p-4 text-center sm:row-span-3 sm:grid-rows-subgrid",
                      dragging && !uploadBusy && "bg-accent",
                    )}
                    role="group"
                    aria-label="Upload plugin ZIP"
                    aria-busy={uploadBusy}
                    onDragOver={(event) => {
                      event.preventDefault()
                      event.stopPropagation()
                      if (!uploadBusy) setDragging(true)
                    }}
                    onDragLeave={(event) => {
                      if (!event.currentTarget.contains(event.relatedTarget as Node | null))
                        setDragging(false)
                    }}
                    onDrop={(event) => {
                      event.preventDefault()
                      event.stopPropagation()
                      setDragging(false)
                      if (!uploadBusy) selectPluginZip(Array.from(event.dataTransfer.files))
                    }}
                  >
                    <Input
                      ref={fileInput}
                      type="file"
                      accept=".zip,application/zip,application/x-zip-compressed"
                      aria-label="Choose plugin ZIP"
                      className="sr-only"
                      disabled={uploadBusy || packageInstalled}
                      onChange={(event) => {
                        selectPluginZip(Array.from(event.target.files || []))
                        event.target.value = ""
                      }}
                    />
                    {uploadBusy ? (
                      <>
                        <Spinner aria-hidden="true" className="size-6" />
                        <p
                          role="status"
                          className="flex self-stretch items-center justify-center text-sm"
                        >
                          {uploadState === "reloading"
                            ? "Saving your workspace and reloading…"
                            : `Installing ${purchasedPlanName}…`}
                        </p>
                      </>
                    ) : packageInstalled ? (
                      <>
                        <Check aria-hidden="true" className="size-6" />
                        <p className="flex self-stretch items-center justify-center text-sm font-medium">
                          Installed and active
                        </p>
                        {onReloadEditor ? (
                          <Button onClick={() => void reloadEditor()}>Reload editor</Button>
                        ) : (
                          <p className="text-xs text-muted-foreground">
                            Reload this page after saving your work.
                          </p>
                        )}
                      </>
                    ) : (
                      <>
                        <Upload aria-hidden="true" className="size-6 text-muted-foreground" />
                        {pluginZip ? (
                          <>
                            <p
                              className="flex max-w-full self-stretch items-center justify-center break-all text-sm"
                              aria-live="polite"
                            >
                              {pluginZip.name}
                            </p>
                            <div className="flex flex-wrap justify-center gap-2">
                              <Button onClick={() => void installSelectedZip()}>Install</Button>
                              <Button
                                variant="outline"
                                onClick={() => {
                                  setPluginZip(null)
                                  setUploadError("")
                                }}
                                aria-label="Remove selected ZIP"
                              >
                                <X aria-hidden="true" className="size-3.5" />
                                Remove
                              </Button>
                            </div>
                          </>
                        ) : (
                          <>
                            <p className="flex self-stretch items-center justify-center text-sm">
                              Upload (drag and drop) to install your plugin
                            </p>
                            <Button variant="outline" onClick={() => fileInput.current?.click()}>
                              Browse
                            </Button>
                          </>
                        )}
                      </>
                    )}
                  </div>
                </div>
                {uploadError ? (
                  <Alert variant="destructive">
                    <AlertDescription>{uploadError}</AlertDescription>
                  </Alert>
                ) : null}
                <div className="flex flex-col gap-2">
                  <Collapsible className="text-sm text-muted-foreground">
                    <CollapsibleTrigger asChild>
                      <Button
                        variant="ghost"
                        className="group justify-start px-0 text-sm text-foreground"
                      >
                        <ChevronRight className="size-4 group-data-[state=open]:rotate-90" />
                        Other ways to download
                      </Button>
                    </CollapsibleTrigger>
                    <CollapsibleContent className="space-y-3 pt-3">
                      <p>
                        You can always download {purchasedPlanName} from your{" "}
                        <a
                          className="underline"
                          href={dashboardUrl}
                          target="_blank"
                          rel="noreferrer"
                        >
                          MapSVG Dashboard
                        </a>
                        .
                      </p>
                      {accountEmail ? (
                        <p>
                          Sign in with{" "}
                          <strong className="break-all font-medium">{accountEmail}</strong> — the
                          same email you used to activate Lite.
                        </p>
                      ) : (
                        <p>Sign in with the same email you used to activate Lite.</p>
                      )}
                    </CollapsibleContent>
                  </Collapsible>
                  <Collapsible className="text-sm text-muted-foreground">
                    <CollapsibleTrigger asChild>
                      <Button
                        variant="ghost"
                        className="group justify-start px-0 text-sm text-foreground"
                      >
                        <ChevronRight className="size-4 group-data-[state=open]:rotate-90" />
                        How to install manually
                      </Button>
                    </CollapsibleTrigger>
                    <CollapsibleContent className="pt-2">
                      <ol className="list-decimal space-y-2 pl-5">
                        <li>
                          Download the plugin ZIP, then drop it in the upload zone above or use
                          Browse.
                        </li>
                        <li>
                          Click Install to install and activate the {purchasedPlanName} add-on. You
                          can also use Plugins → Add New Plugin → Upload Plugin.
                        </li>
                        <li>
                          Keep MapSVG Lite active. Your license key stays the same. Reload the
                          editor after installation.
                        </li>
                      </ol>
                    </CollapsibleContent>
                  </Collapsible>
                </div>
              </div>
            ) : (
              <div className="flex min-h-full flex-col justify-center gap-4 text-center">
                {phase === "confirming" ? <Spinner className="mx-auto size-6" /> : null}
                <p role="status" className="text-sm">
                  {phase === "verification-error"
                    ? "Your payment status needs to be checked."
                    : "Confirming your upgrade…"}
                </p>
                {verificationError ? (
                  <Alert variant="destructive">
                    <AlertDescription>{verificationError}</AlertDescription>
                  </Alert>
                ) : null}
                {phase === "verification-error" ? (
                  <Button
                    className="mx-auto"
                    onClick={() => {
                      setVerificationError("")
                      if (purchase) setCheckoutLoading(true)
                      setPhase(purchase ? "checkout" : "confirming")
                    }}
                  >
                    Check payment status
                  </Button>
                ) : null}
              </div>
            )
          ) : (
            <div className="space-y-5">
              {error ? (
                <Alert variant="destructive">
                  <AlertDescription>
                    {error}
                    <Button
                      variant="link"
                      onClick={() => {
                        const plan = catalogue?.plans.find(
                          (item) => item.priceId === selectedPriceId,
                        )
                        if (plan) void selectPlan(plan)
                        else void load()
                      }}
                    >
                      Try again
                    </Button>
                  </AlertDescription>
                </Alert>
              ) : null}
              {catalogue?.plans.length ? (
                <div ref={choices} className="space-y-3">
                  <p className="mx-px px-4 text-sm font-medium">Choose your plan</p>
                  <RadioGroup
                    value={selectedPriceId}
                    aria-label="Upgrade plan"
                    disabled={processing || loading}
                    onValueChange={(priceId) => {
                      const plan = catalogue.plans.find((item) => item.priceId === priceId)
                      if (plan && !processing) void selectPlan(plan)
                    }}
                    className="gap-1 rounded-lg border"
                  >
                    {catalogue.plans.map((plan, index) => (
                      <label
                        key={plan.priceId}
                        htmlFor={`${choiceId}-${index}`}
                        className={cn(
                          "flex cursor-pointer items-center gap-3 rounded-md px-4 py-3 text-sm ring-1 ring-inset",
                          selectedPriceId === plan.priceId ? "ring-foreground" : "ring-transparent",
                        )}
                      >
                        <span className="flex min-w-0 flex-1 flex-wrap items-center justify-between gap-2">
                          <span className="space-y-1">
                            <span className="block font-medium">
                              {PLAN_NAMES[plan.slug] || plan.title}
                            </span>
                            <span className="block space-y-1 text-xs text-muted-foreground">
                              <span className="flex items-center gap-1.5">
                                <Globe aria-hidden="true" className="size-3.5 shrink-0" />
                                {plan.numDomainsMax === 0
                                  ? "Unlimited sites"
                                  : `${plan.numDomainsMax} ${plan.numDomainsMax === 1 ? "site" : "sites"}`}
                              </span>
                              {PLAN_AI_USAGE_LABELS[plan.slug] ? (
                                <span className="flex items-center gap-1.5">
                                  <Sparkles aria-hidden="true" className="size-3.5 shrink-0" />
                                  {PLAN_AI_USAGE_LABELS[plan.slug]}
                                </span>
                              ) : null}
                              {plan.updateRequired ? (
                                <span className="text-amber-700">Update Lite to continue</span>
                              ) : null}
                            </span>
                          </span>
                          <strong className="font-semibold tabular-nums">{planPrice(plan)}</strong>
                        </span>
                        <RadioGroupItem
                          id={`${choiceId}-${index}`}
                          value={plan.priceId}
                          aria-label={`${PLAN_NAMES[plan.slug] || plan.title} · ${planPrice(plan)}`}
                        />
                      </label>
                    ))}
                  </RadioGroup>
                  <p className="mx-px px-4 text-xs text-muted-foreground">
                    Your license key, connected sites and purchased AI credits stay with your
                    license.
                  </p>
                </div>
              ) : !loading && !error ? (
                <p className="text-sm text-muted-foreground">
                  No upgrade plans are available for this license.
                </p>
              ) : null}
              {selectedPlan?.updateRequired ? (
                <Alert>
                  <AlertDescription className="space-y-3">
                    <p>
                      {PLAN_NAMES[selectedPlan.slug] || selectedPlan.title}
                      {selectedPlan.version ? ` ${selectedPlan.version}` : ""} requires MapSVG Lite{" "}
                      {selectedPlan.requiresLiteVersion} or newer. Update Lite before purchasing.
                    </p>
                    <Button asChild>
                      <a
                        href={new URL("update-core.php", window.location.href).href}
                        target="_blank"
                        rel="noreferrer"
                      >
                        Open WordPress updates
                        <ExternalLink aria-hidden="true" className="size-3.5" />
                      </a>
                    </Button>
                    <p className="text-xs text-muted-foreground">
                      After updating Lite, reload this editor to continue.
                    </p>
                  </AlertDescription>
                </Alert>
              ) : null}
              {loading || checkoutLoading || purchase ? (
                <div
                  className="relative"
                  style={{ height: frameHeight }}
                  data-slot="upgrade-checkout-frame"
                  aria-busy={loading || checkoutLoading}
                >
                  {purchase ? (
                    <UpgradeCheckoutFrame
                      key={purchase.purchaseId}
                      frame={frame}
                      checkoutUrl={purchase.checkoutUrl}
                      onNavigationStart={resetCheckoutScroll}
                    />
                  ) : null}
                  {loading || checkoutLoading ? (
                    <div className="absolute inset-0 bg-background">
                      <div
                        role="status"
                        className="sticky top-0 flex h-40 items-center justify-center gap-2 text-sm text-muted-foreground"
                      >
                        <Spinner aria-hidden="true" />
                        {loading
                          ? "Loading upgrade plans…"
                          : purchase
                            ? "Loading payment form…"
                            : "Preparing checkout…"}
                      </div>
                    </div>
                  ) : null}
                </div>
              ) : null}
            </div>
          )}
        </div>
        <DialogFooter className="shrink-0 border-t border-border px-6 py-4">
          <Button
            variant="outline"
            disabled={locked}
            onClick={() => {
              if (!locked) onOpenChange(false)
            }}
          >
            {phase === "complete" ? null : <ArrowLeft className="size-4" />}
            {phase === "complete" ? "Done" : "Go back"}
          </Button>
          {locked ? (
            <Button variant="outline" disabled>
              Open MapSVG Dashboard
              <ExternalLink className="size-3.5" />
            </Button>
          ) : (
            <Button asChild variant="outline">
              <a href={dashboardUrl} target="_blank" rel="noreferrer">
                Open MapSVG Dashboard
                <ExternalLink className="size-3.5" />
              </a>
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
